import{c as s,$ as e,Q as o,j as l,g as a,o as n,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const g="/img/ru/front/workshop.webp",y=JSON.parse('{"title":"Оборудование и активы","description":"Универсальный учет оборудования, станков, приборов, инструментов и расчет их амортизации в ОмниКрафт ЕРП.","frontmatter":{"title":"Оборудование и активы","description":"Универсальный учет оборудования, станков, приборов, инструментов и расчет их амортизации в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-25","order":1},"headers":[],"relativePath":"ru/docs/resources/assets.md","filePath":"ru/docs/resources/assets.md","lastUpdated":1795564800000}'),h={name:"ru/docs/resources/assets.md"},c={id:"оборудование-и-активы",tabindex:"-1"};function u(p,t,f,m,b,q){const r=e("DocIcon");return o(),l("div",null,[a("h1",c,[n(r,{name:"workshop"}),t[0]||(t[0]=i(" Оборудование и активы ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#оборудование-и-активы","aria-label":'Permalink to "Оборудование и активы"'},"​",-1))]),t[2]||(t[2]=d('<figure class="doc-image craft-window-frame" data-title="Оборудование и активы — ОмниКрафт ЕРП"><img src="'+g+'" alt="Главное окно вкладки «Мастерская» (Оборудование и активы)"><figcaption>Главное окно вкладки «Мастерская» (Оборудование и активы)</figcaption></figure><p>Вкладка <strong>«Мастерская»</strong> в программе служит единым центром управления долгосрочным имуществом вашего дела. Вне зависимости от направления — создаёте ли вы вещи вручную, управляете сервисным центром, развиваете магазин или продаёте товары на маркетплейсах — материальная база формирует фундамент вашего капитала.</p><p>Это не просто перечень станков и инструментов на полках. Раздел связывает физические предметы с управленческим балансом: показывает реальную текущую стоимость вашего бизнеса, автоматически начисляет износ и помогает закладывать амортизацию в расценки.</p><hr><h2 id="экономическии-смысл-перенос-ценности-в-баланс" tabindex="-1">Экономический смысл: Перенос ценности в баланс <a class="header-anchor" href="#экономическии-смысл-перенос-ценности-в-баланс" aria-label="Permalink to &quot;Экономический смысл: Перенос ценности в баланс&quot;">​</a></h2><p>В повседневной жизни покупку дорогого предмета часто воспринимают как денежную потерю. В профессиональном учете <strong>ОмниКрафт ЕРП</strong> приобретение средств производства работает по правилу сохранения капитала:</p><ol><li><strong>Капитал не уменьшается при покупке.</strong> Когда вы покупаете лазерный станок, паяльную станцию или термопринтер за 100 000 рублей, вы не теряете эти деньги. Вы меняете форму актива: свободные безналичные деньги из кассы превращаются в работающее оборудование. Общая ценность вашего бизнеса в отчете «Капитал» остаётся неизменной.</li><li><strong>Бережливый расчет износа.</strong> Промышленные бухгалтерские системы требуют высчитывать отработанные машино-часы по каждому агрегату. В ОмниКрафт ЕРП используется прямолинейный метод списания: <ul><li>Программа делит стоимость на срок службы и выводит <strong>точную сумму ежемесячного износа всей базы</strong>.</li><li>Зная эту сумму и объем выпуска или оказанных услуг, вы закладываете норматив износа в калькуляцию или накладные расходы. Оборудование планомерно окупает себя с каждого выполненного заказа.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Линейная амортизация без формул</p><p>Если гравер куплен за 120 000 рублей на 5 лет (60 месяцев), программа ежемесячно уменьшает его остаточную стоимость на 2 000 рублей. В Капитале всегда отражается честная рыночная цена с учетом возраста станка, а не иллюзорная первоначальная сумма.</p></div><hr><h2 id="два-режима-учета-имущество-и-расходники" tabindex="-1">Два режима учета: Имущество и Расходники <a class="header-anchor" href="#два-режима-учета-имущество-и-расходники" aria-label="Permalink to &quot;Два режима учета: Имущество и Расходники&quot;">​</a></h2><p>В верхней части экрана расположен переключатель между двумя принципиально разными категориями материальных ресурсов:</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Имущество (Основные средства)</th><th style="width:50%;">Расходники (Оснастка цеха)</th></tr></thead><tbody><tr><td><strong>Назначение:</strong> Долгосрочные основные средства (станки, верстаки, транспорт).</td><td><strong>Назначение:</strong> Быстроизнашиваемая рабочая оснастка (свёрла, фрезы, диски, кисти).</td></tr><tr><td><strong>Срок службы:</strong> От 1 года до десятков лет (задаётся в карточке).</td><td><strong>Срок службы:</strong> Не задаётся (короткий жизненный цикл).</td></tr><tr><td><strong>Влияние на баланс:</strong> Ежемесячная линейная амортизация в Капитал.</td><td><strong>Влияние на баланс:</strong> Прямой производственный расход в кассе (ДДС).</td></tr></tbody></table><h3 id="_1-долгосрочное-имущество" tabindex="-1">1. Долгосрочное имущество <a class="header-anchor" href="#_1-долгосрочное-имущество" aria-label="Permalink to &quot;1. Долгосрочное имущество&quot;">​</a></h3><p>Основные материальные средства, рассчитанные на долгий срок службы (станки, верстаки, приборы, оргтехника, мебель, автомобили).</p><ul><li>Для каждого объекта указывается <strong>срок службы</strong> в годах или месяцах.</li><li>Программа ежемесячно начисляет амортизацию, плавно снижая балансовую стоимость.</li><li>Остаточная стоимость объектов суммируется и формирует блок производственных активов в общем Капитале.</li></ul><h3 id="_2-расходники-и-рабочая-оснастка" tabindex="-1">2. Расходники и рабочая оснастка <a class="header-anchor" href="#_2-расходники-и-рабочая-оснастка" aria-label="Permalink to &quot;2. Расходники и рабочая оснастка&quot;">​</a></h3><p>Вспомогательные элементы и инструмент с коротким жизненным циклом (свёрла, фрезы, насадки, отрезные диски, кисти, технические жидкости).</p><ul><li>Для расходников <strong>не задается срок службы</strong> и не начисляется износ.</li><li>Их стоимость в полном объеме учитывается в расходах в журнале движения денег (ДДС) в момент приобретения.</li><li>В карточке нажмите <strong>«Пополнить (Докупить)»</strong>. Укажите дату и заполните <strong>«Сумма закупки»</strong> или <strong>«Доставка»</strong>. Если оплачены оба расхода, заполните оба поля. После сохранения суммы увеличат учётную стоимость расходника, а закупка и доставка появятся в журнале движения денег отдельными записями.</li></ul><hr><h2 id="специфика-учета-по-направлениям" tabindex="-1">Специфика учета по направлениям <a class="header-anchor" href="#специфика-учета-по-направлениям" aria-label="Permalink to &quot;Специфика учета по направлениям&quot;">​</a></h2><p>Базовый механизм добавления и списания универсален, однако специфика зависит от характера вашей деятельности.</p><h3 id="services" tabindex="-1">В сфере услуг <a class="header-anchor" href="#services" aria-label="Permalink to &quot;В сфере услуг {#services}&quot;">​</a></h3><p>В сервисном центре, ремонтной мастерской, студии или салоне оборудование формирует рабочие посты мастеров:</p><ul><li><strong>Что вносить в Имущество:</strong> диагностические сканеры, паяльные комплексы, компрессоры, подъемники, стерилизаторы, профессиональные фены, кушетки, клиентскую мебель и компьютеры администратора.</li><li><strong>Что вносить в Расходники:</strong> защитные накладки, одноразовые насадки, припой, жала для паяльников, технические салфетки и смазки.</li><li><strong>Как окупать износ:</strong> общую сумму ежемесячной амортизации оборудования разделите на среднее количество заказ-нарядов в месяц и включите эту цифру в базовую стоимость нормо-часа или фиксированную наценку за операцию.</li></ul><h3 id="production" tabindex="-1">В производстве <a class="header-anchor" href="#production" aria-label="Permalink to &quot;В производстве {#production}&quot;">​</a></h3><p>В ремесленном или серийном цехе активы напрямую участвуют в преобразовании сырья в товар:</p><ul><li><strong>Что вносить в Имущество:</strong> раскройные столы, лазерные и фрезерные станки с числовым программным управлением, швейные машины, прессы для тиснения, печи для обжига и сушильные камеры.</li><li><strong>Что вносить в Расходники:</strong> сменные лезвия, швейные иглы, шлифовальные круги, зажимы и полировальные пасты.</li><li><strong>Как окупать износ:</strong> в модуле «Калькулятор» заложите норматив износа оборудования в технологическую карту изделия, чтобы себестоимость каждого выпущенного предмета резервировала фонд на обновление станков.</li></ul><h3 id="trade" tabindex="-1">В торговле и у селлеров маркетплейсов <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;В торговле и у селлеров маркетплейсов {#trade}&quot;">​</a></h3><p>В ритейле и складской логистике оборудование обеспечивает упаковку, маркировку и товародвижение:</p><ul><li><strong>Что вносить в Имущество:</strong> термопринтеры для печати этикеток и штрихкодов, сканеры, запайщики пакетов, торговые витрины, стеллажные системы и электронные весы.</li><li><strong>Что вносить в Расходники:</strong> скотч, пузырьковую пленку, упаковочные пакеты и маркировочные ленты.</li><li><strong>Как окупать износ:</strong> амортизация складского оборудования включается в накладные коммерческие расходы на единицу отправления.</li></ul><hr><h2 id="работа-с-карточкои-актива-5-жизненных-сценариев" tabindex="-1">Работа с карточкой актива: 5 жизненных сценариев <a class="header-anchor" href="#работа-с-карточкои-актива-5-жизненных-сценариев" aria-label="Permalink to &quot;Работа с карточкой актива: 5 жизненных сценариев&quot;">​</a></h2><p>При нажатии кнопки <strong>«Добавить актив»</strong> открывается окно ввода параметров. Ниже разобраны ключевые жизненные ситуации, с которыми вы столкнетесь на практике:</p><p>Чтобы поставить оборудование на учёт через внешнего агента, включите доверенный режим в <a href="./../global-settings">общих настройках</a>. Передайте название, категорию, цену покупки и срок службы. Стоимость доставки укажите отдельно. Она войдёт в стоимость оборудования, а расходы на покупку и доставку появятся в движении денег отдельными записями.</p><h3 id="сценарии-1-первичныи-ввод-при-переходе-на-программу" tabindex="-1">Сценарий 1: Первичный ввод при переходе на программу <a class="header-anchor" href="#сценарии-1-первичныи-ввод-при-переходе-на-программу" aria-label="Permalink to &quot;Сценарий 1: Первичный ввод при переходе на программу&quot;">​</a></h3><p>Вам не нужно искать старые чеки пятилетней давности. Оцените станок по текущей рыночной цене подержанного аналога (на электронных досках объявлений) и укажите, сколько лет он ещё прослужит (например, 3 года). Программа начнет расчет износа с этой справедливой точки без искажения баланса.</p><h3 id="сценарии-2-безвозмездное-поступление-из-личного-гаража-или-по-гранту" tabindex="-1">Сценарий 2: Безвозмездное поступление (из личного гаража или по гранту) <a class="header-anchor" href="#сценарии-2-безвозмездное-поступление-из-личного-гаража-или-по-гранту" aria-label="Permalink to &quot;Сценарий 2: Безвозмездное поступление (из личного гаража или по гранту)&quot;">​</a></h3><p>Если вы принесли в мастерскую собственный инструмент, купленный до открытия дела, или получили оборудование по субсидии:</p><ul><li>В карточке укажите его оценочную стоимость.</li><li>В поле способа оплаты не привязывайте расход к кассе (ДДС).</li><li>Имущество появится на балансе и увеличит собственный капитал бизнеса, не создавая искусственной дыры в кассе.</li></ul><h3 id="сценарии-3-переоценка-из-за-инфляции" tabindex="-1">Сценарий 3: Переоценка из-за инфляции <a class="header-anchor" href="#сценарии-3-переоценка-из-за-инфляции" aria-label="Permalink to &quot;Сценарий 3: Переоценка из-за инфляции&quot;">​</a></h3><p>Если цена станка на вторичном рынке изменилась, нажмите <strong>«Переоценить»</strong> в карточке оборудования. Укажите новую стоимость, дату и оставшийся срок службы в годах. Оставьте флажок <strong>«Платное обслуживание / ремонт (расход в ДДС)»</strong> снятым и нажмите <strong>«Сохранить»</strong>. Программа пересчитает остаточную стоимость и ежемесячную амортизацию с даты переоценки. В движении денег новой записи не появится.</p><h3 id="сценарии-4-текущее-обслуживание-против-модернизации" tabindex="-1">Сценарий 4: Текущее обслуживание против модернизации <a class="header-anchor" href="#сценарии-4-текущее-обслуживание-против-модернизации" aria-label="Permalink to &quot;Сценарий 4: Текущее обслуживание против модернизации&quot;">​</a></h3><p>Важно разделять два типа расходов на технику:</p><ul><li><strong>Текущий ремонт и ТО (замена масла, заточка, замена ремня):</strong> проводится как обычный расход в модуле движения денег (ДДС) со статьей «Обслуживание оборудования». Балансовая цена станка при этом не увеличивается.</li><li><strong>Капитальная модернизация (например, замена двигателя):</strong> нажмите <strong>«Переоценить»</strong> и заполните новые параметры оборудования. Чтобы одновременно провести оплату, установите флажок <strong>«Платное обслуживание / ремонт (расход в ДДС)»</strong>, введите сумму оплаты и нажмите <strong>«Сохранить»</strong>. В журнале оборудования появится переоценка, а в движении денег — расход. Если оплату уже провели, оставьте флажок снятым.</li></ul><h3 id="сценарии-5-архивирование-и-восстановление" tabindex="-1">Сценарий 5: Архивирование и восстановление <a class="header-anchor" href="#сценарии-5-архивирование-и-восстановление" aria-label="Permalink to &quot;Сценарий 5: Архивирование и восстановление&quot;">​</a></h3><p>Выберите <strong>«Отправить в архив»</strong> в строке или карточке. Карточка уйдёт из основного списка, а оборудование исключится из расчёта остаточной стоимости и амортизации мастерской. История сохранится.</p><p>Чтобы вернуть карточку, откройте <strong>«Архив оборудования»</strong> на вкладке <strong>«Имущество»</strong> или <strong>«Архив расходников»</strong> на вкладке <strong>«Расходники»</strong> и нажмите <strong>«Восстановить»</strong>. При продаже оборудования выручку проведите в журнале движения денег.</p><hr><h2 id="навигация-фильтры-и-порядок-в-реестре" tabindex="-1">Навигация, фильтры и порядок в реестре <a class="header-anchor" href="#навигация-фильтры-и-порядок-в-реестре" aria-label="Permalink to &quot;Навигация, фильтры и порядок в реестре&quot;">​</a></h2><p>Когда список имущества превышает несколько десятков позиций, используйте встроенные инструменты навигации верхней панели:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Инструмент</th><th style="text-align:left;">Назначение</th><th style="text-align:left;">Практическая польза</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Поиск по названию</strong></td><td style="text-align:left;">Мгновенная фильтрация по подстроке</td><td style="text-align:left;">Поиск инструмента по марке, инвентарному номеру или модели</td></tr><tr><td style="text-align:left;"><strong>Категории</strong></td><td style="text-align:left;">Группировка объектов по типам</td><td style="text-align:left;">Разделение на станки, приборы, электронику, мебель</td></tr><tr><td style="text-align:left;"><strong>Локации</strong></td><td style="text-align:left;">Фильтр по местам нахождения</td><td style="text-align:left;">Быстрый учет оборудования в основном цехе, на складе или в филиале</td></tr><tr><td style="text-align:left;"><strong>Сортировка колонок</strong></td><td style="text-align:left;">Сортировка по цене, дате ввода или износу</td><td style="text-align:left;">Контроль самых дорогих позиций или станков с истекающим сроком</td></tr><tr><td style="text-align:left;"><strong>Сброс фильтров</strong></td><td style="text-align:left;">Кнопка сброса параметров</td><td style="text-align:left;">Мгновенный возврат к полному списку всех активов</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Справочники категорий и мест хранения</p><p>Нажмите карандаш рядом с полем категории или места хранения, чтобы добавить, переименовать или удалить запись в текущем пространстве. Новое название появится во всех связанных карточках, включая архивные. При удалении поле в этих карточках очищается. Если запись используется, программа покажет число связанных карточек перед подтверждением.</p><p>Внешний агент может прочитать справочники. Для добавления, переименования и удаления через агента включите доверенный режим в <a href="./../global-settings">общих настройках</a>.</p></div><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если амортизация станка начисляется быстрее или медленнее реального износа?</summary><div class="faq-content"><p>Откройте карточку станка и измените срок полезного использования в месяцах либо ликвидационную стоимость. При необходимости выполните разовую переоценку через операцию «Модернизация / Переоценка» для приведения балансовой стоимости к рыночной.</p></div></details><details class="faq-item"><summary class="faq-summary">Почему система блокирует удаление старого станка из реестра?</summary><div class="faq-content"><p>Прямое удаление запрещено, если по активу зафиксированы исторические затраты на ремонт или амортизационные проводки. Откройте карточку оборудования и выберите действие «Списать» или «Архивировать» — это сохранит чистоту финансовой отчетности.</p></div></details><details class="faq-item"><summary class="faq-summary">Как учесть оборудование, внесенное мастером из личного имущества до запуска программы?</summary><div class="faq-content"><p>Внесите карточку актива с датой фактической покупки и остаточной стоимостью. В поле «Способ финансирования» укажите личные инвестиции мастера — оборудование пополнит баланс предприятия без ложного списания денег из операционной кассы.</p></div></details></div>',55))])}const _=s(h,[["render",u]]);export{y as __pageData,_ as default};
